	@Test
	void preservesChecksummedPromotedArtifactsUntilRecoveryValidationFinishes() throws Exception {
		Path target = Files.createDirectory(temporaryDirectory.resolve("recoverable-store"));
		String generationName = ".lmdb-bulk-generation-recovery-test";
		Path artifact = target.resolve("values");
		byte[] artifactBytes = "complete-value-store".getBytes(StandardCharsets.UTF_8);
		Files.write(artifact, artifactBytes);

		Properties marker = new Properties();
		marker.setProperty("version", "2");
		marker.setProperty("generation", generationName);
		storeProperties(target.resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME), marker);

		Properties manifest = new Properties();
		manifest.setProperty("version", "2");
		manifest.setProperty("generation", generationName);
		manifest.setProperty("artifact.count", "1");
		manifest.setProperty("artifact.0", "values");
		manifest.setProperty("artifact.0.type", "file");
		manifest.setProperty("artifact.0.size", Long.toString(artifactBytes.length));
		manifest.setProperty("artifact.0.sha256",
				HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(artifactBytes)));
		manifest.setProperty("result.parsed-statements", "3");
		manifest.setProperty("result.stored-statements", "2");
		manifest.setProperty("result.persisted-values", "4");
		manifest.setProperty("result.inline-values", "1");
		manifest.setProperty("result.temporary-bytes", "1024");
		manifest.setProperty("result.elapsed-millis", "15");
		manifest.setProperty("result.map-growth-count", "2");
		storeProperties(target.resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME), manifest);

		try (LmdbBulkLoadGeneration recovered = LmdbBulkLoadGeneration.create(target)) {
			assertThat(artifact).hasBinaryContent(artifactBytes);
			assertThat(target.resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME)).exists();

			Method finish = LmdbBulkLoadGeneration.class.getDeclaredMethod("finishRecoveredPublication");
			finish.setAccessible(true);
			finish.invoke(recovered);
		}

		assertThat(artifact).hasBinaryContent(artifactBytes);
		assertThat(target.resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME)).doesNotExist();
		assertThat(target.resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME)).doesNotExist();
	}

