	@Test
	void loadsAndPublishesAQueryReadyDeduplicatedStore() throws Exception {
		String input = """
				<urn:subject> <urn:predicate> "hello"@EN .
				<urn:subject> <urn:predicate> "hello"@en .
				<urn:subject> <urn:predicate> <urn:object> <urn:graph> .
				<urn:subject> <urn:predicate> <urn:object> <urn:graph> .
				""";
		Path target = temporaryDirectory.resolve("store");
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,psoc");

		LmdbBulkLoader.Result result = LmdbBulkLoader.builder(target, config)
				.partitionCount(4)
				.build()
				.load(new ByteArrayInputStream(input.getBytes(StandardCharsets.UTF_8)), "urn:bulk-test:",
						RDFFormat.NQUADS);

		assertThat(result.parsedStatements()).isEqualTo(4);
		assertThat(result.storedStatements()).isEqualTo(2);

		SailRepository repository = new SailRepository(new LmdbStore(target.toFile(), config));
		repository.init();
		try {
			var valueFactory = SimpleValueFactory.getInstance();
			try (RepositoryConnection connection = repository.getConnection()) {
				assertThat(connection.size()).isEqualTo(2);
				assertThat(connection.hasStatement(valueFactory.createIRI("urn:subject"),
						valueFactory.createIRI("urn:predicate"), valueFactory.createLiteral("hello", "en"), false))
								.isTrue();
			}
		} finally {
			repository.shutDown();
		}
	}

