	@Test
	void fastParserReadsGzipAndReportsMalformedInputWithoutPublishing() throws Exception {
		String input = """
				<urn:s> <urn:p> "compressed"@EN .
				<urn:s> <urn:p> <urn:o> <urn:g> .
				""";
		ByteArrayOutputStream compressed = new ByteArrayOutputStream();
		try (GZIPOutputStream gzip = new GZIPOutputStream(compressed)) {
			gzip.write(input.getBytes(StandardCharsets.UTF_8));
		}
		Path compressedTarget = temporaryDirectory.resolve("gzip-store");

		LmdbBulkLoader.Result result = LmdbBulkLoader.builder(compressedTarget, new LmdbStoreConfig("spoc,psoc"))
				.parserMode(LmdbBulkLoader.ParserMode.FAST)
				.partitionCount(4)
				.build()
				.load(new ByteArrayInputStream(compressed.toByteArray()), "urn:gzip:", RDFFormat.NQUADS);

		assertThat(result.parsedStatements()).isEqualTo(2);
		assertThat(readStatements(compressedTarget)).hasSize(2);

		Path rioCompressedTarget = temporaryDirectory.resolve("rio-gzip-store");
		LmdbBulkLoader.Result rioResult = LmdbBulkLoader
				.builder(rioCompressedTarget, new LmdbStoreConfig("spoc,psoc"))
				.parserMode(LmdbBulkLoader.ParserMode.RIO)
				.partitionCount(4)
				.build()
				.load(new ByteArrayInputStream(compressed.toByteArray()), "urn:gzip:", RDFFormat.NQUADS);

		assertThat(rioResult.parsedStatements()).isEqualTo(2);
		assertThat(Models.isomorphic(readStatements(compressedTarget), readStatements(rioCompressedTarget))).isTrue();

		Path malformedTarget = temporaryDirectory.resolve("malformed-store");
		assertThatThrownBy(() -> LmdbBulkLoader
				.builder(malformedTarget, new LmdbStoreConfig("spoc,psoc"))
				.parserMode(LmdbBulkLoader.ParserMode.AUTO)
				.partitionCount(4)
				.build()
				.load(new ByteArrayInputStream("<urn:s> <urn:p> \"unterminated\n".getBytes(StandardCharsets.UTF_8)),
						"urn:malformed:", RDFFormat.NQUADS))
								.isInstanceOf(RDFParseException.class)
								.hasMessageContaining("Unterminated literal")
								.hasMessageContaining("line 1");
		assertThat(malformedTarget).doesNotExist();
	}

