	@Test
	void fastAndRioParsersRejectMalformedLanguageTags() {
		List<String> malformed = List.of(
				"<urn:s> <urn:p> \"value\"@-en .\n",
				"<urn:s> <urn:p> \"value\"@en--us .\n");

		for (int inputIndex = 0; inputIndex < malformed.size(); inputIndex++) {
			for (LmdbBulkLoader.ParserMode mode : List.of(LmdbBulkLoader.ParserMode.FAST,
					LmdbBulkLoader.ParserMode.RIO)) {
				Path target = temporaryDirectory.resolve("malformed-language-" + inputIndex + "-" + mode);
				byte[] input = malformed.get(inputIndex).getBytes(StandardCharsets.UTF_8);
				assertThatThrownBy(() -> LmdbBulkLoader.builder(target, new LmdbStoreConfig("spoc,psoc"))
						.parserMode(mode)
						.partitionCount(4)
						.build()
						.load(new ByteArrayInputStream(input), "urn:malformed:", RDFFormat.NQUADS))
								.as(mode + ": " + malformed.get(inputIndex))
								.isInstanceOf(RDFParseException.class);
				assertThat(target).doesNotExist();
			}
		}
	}

