	@Test
	void cancellationCleansOwnedTargetAndWorkspaceWithoutClosingCallerInput() throws Exception {
		StringBuilder input = new StringBuilder();
		for (int i = 0; i < 2_000; i++) {
			input.append("<urn:s:").append(i).append("> <urn:p> <urn:o:").append(i).append("> .\n");
		}
		Path target = temporaryDirectory.resolve("cancelled-store");
		Path workspaceParent = Files.createDirectory(temporaryDirectory.resolve("cancelled-workspaces"));
		CloseDetectingInputStream callerOwned = new CloseDetectingInputStream(
				input.toString().getBytes(StandardCharsets.UTF_8));
		AtomicInteger checks = new AtomicInteger();

		assertThatThrownBy(() -> LmdbBulkLoader.builder(target, new LmdbStoreConfig("spoc,psoc"))
				.partitionCount(8)
				.maxOpenFiles(3)
				.temporaryDirectory(workspaceParent)
				.cancellationSignal(() -> checks.incrementAndGet() >= 64)
				.build()
				.load(callerOwned, "urn:cancel:", RDFFormat.NQUADS))
						.isInstanceOf(CancellationException.class);

		assertThat(callerOwned.closed).isFalse();
		assertThat(target).doesNotExist();
		try (var children = Files.list(workspaceParent)) {
			assertThat(children).isEmpty();
		}
	}

